  '''voice_script''': '''প্রিয় ছাত্রছাত্রীরা, আজ আমরা আলোচনা করব শিল্পবিপ্লব কী, সেটা নিয়ে। তোমরা নিশ্চয়ই নামটা শুনেছো — শিল্পবিপ্লব। কিন্তু আসলে কী এই শিল্পবিপ্লব? সহজ ভাষায় বলি। ধরো, আগে মানুষ হাতে চরকা কেটে কাপড় বুনত। ঘণ্টার পর ঘণ্টা কাজ করে অল্প কাপড় তৈরি হত। কিন্তু শিল্পবিপ্লবের পর যন্ত্র এল, বাষ্পীয় ইঞ্জিন এল — তখন কয়েক ঘণ্টায় হাজার হাজার মিটার কাপড় তৈরি করা সম্ভব হল। এই যে ব্যাপারটা — উৎপাদন ব্যবস্থায় যন্ত্রের আগমন ও দ্রুত পরিবর্তন — এটাকেই বলে শিল্পবিপ্লব। অষ্টাদশ শতাব্দীর শেষার্ধে ইংল্যান্ডে এই বিপ্লব শুরু হয়। এরপর ধীরে ধীরে ইউরোপের অন্যান্য দেশে ছড়িয়ে পড়ে — ফ্রান্স, জার্মানি, ইতালি, বেলজিয়াম, এমনকি রাশিয়াতেও। এখন পরীক্ষার জন্য একটি গুরুত্বপূর্ণ তথ্য মনে রেখো — "শিল্পবিপ্লব" শব্দটা কিন্তু নতুন নয়। ফরাসি সমাজতত্ত্ববিদ অগাস্ট ব্লাংকি ১৮৩৭ সালে প্রথম শব্দটি ব্যবহার করেন। পরে ১৮৬৭ সালে কার্ল মার্কস তাঁর দাস ক্যাপিটাল বইয়ে শব্দটি প্রয়োগ করেন। তবে শব্দটিকে জনপ্রিয় করেন ইংরেজ ঐতিহাসিক আর্নল্ড টয়েনবি। তিনি অক্সফোর্ড বিশ্ববিদ্যালয়ে বক্তৃতা দিয়ে শিল্পবিপ্লব কথাটি সবার মুখে মুখে নিয়ে আসেন। কিন্তু মজার ব্যাপার হলো, সব ঐতিহাসিক একমত নন। হ্যাজেন ও হেজের মতো ঐতিহাসিকরা বলেন, এটা আসলে কোনো বিপ্লব নয় — এটি একটি বিবর্তন, দীর্ঘ প্রক্রিয়া। আসলে এটা বোঝা গুরুত্বপূর্ণ যে শিল্পপরিবর্তন আকস্মিক নয়, বরং শতাব্দীব্যাপী একটি প্রক্রিয়া। তোমরা পরীক্ষায় কারা কারা শিল্পবিপ্লব শব্দটি ব্যবহার ও জনপ্রিয় করেন — এই নামগুলো অবশ্যই জেনো: অগাস্ট ব্লাংকি, কার্ল মার্কস, আর আর্নল্ড টয়েনবি। এখন সময়কাল নিয়ে কথা বলি। আর্নল্ড টয়েনবি বলেন ১৭৬০ সালে শুরু, আর জার্মান ঐতিহাসিক হফম্যান বলেন ১৭৮০ সালে। বুঝতে পারছ? আসলে শিল্পবিপ্লব হঠাৎ করে একদিন শুরু হয়নি — এটি ছিল একটা দীর্ঘপ্রক্রিয়া, তাই সময় নিয়েও বিতর্ক আছে। ইংল্যান্ডে প্রথম শিল্পবিপ্লবের পথ তৈরি করেছিল কয়েকটি আবিষ্কার: জন কে-র উড়ন্ত মাকু (১৭৩৩), জেমস হারগ্রিভসের স্পিনিং জেনি (১৭৬৫), রিচার্ড আর্করাইটের ওয়াটার ফ্রেম (১৭৬৯), আর জেমস ওয়াটের বাষ্পীয় ইঞ্জিন (১৭৬৯)। এই আবিষ্কারগুলি বস্ত্রশিল্প থেকে শুরু করে পরিবহন, সবক্ষেত্রেই বিপ্লব আনে। তোমাদের পরীক্ষায় এই আবিষ্কার ও আবিষ্কারকদের নাম প্রায়ই আসে, তাই ভালো করে মুখস্থ করো। আশা করি তোমরা সবকিছু বুঝতে পেরেছো। আগামী ক্লাসে আমরা ইংল্যান্ডে শিল্পবিপ্লবের কারণ নিয়ে বিস্তারিত জানব।''',
