  () {
    return {
  '''id''': '''chapter4_topic_2''',
  '''chapterId''': '''chapter4''',
  '''subjectId''': '''history''',
  '''name''': '''ইংল্যান্ডে প্রথম শিল্পবিপ্লবের কারণ''',
  '''order''': 2,
  '''summary''': '''ইংল্যান্ডে প্রথম শিল্পবিপ্লব শুরু হওয়ার পেছনে একাধিক কারণ কাজ করেছিল। কয়লা ও লোহার প্রাচুর্য শিল্পের জ্বালানি ও কাঁচামাল জোগায়। ব্রিটিশ উপনিবেশ থেকে তুলা, পাটসহ কাঁচামাল আসত এবং তৈরি পণ্যের বাজার ছিল। জেমস ওয়াটের বাষ্পীয় ইঞ্জিন শিল্পকারখানায় শক্তি সরবরাহ করে। কৃষি বিপ্লব ও বেষ্টন আইনের ফলে গ্রামের উদ্বৃত্ত শ্রমিক শহরে কারখানায় কাজ নিতে বাধ্য হয়। বাণিজ্য থেকে বিপুল পুঁজি জমা হয় যা কারখানা স্থাপনে ব্যবহৃত হয়। রাজনৈতিক স্থিতিশীলতা ও সম্পত্তির নিরাপত্তা বিনিয়োগকে উৎসাহিত করে। ইংল্যান্ডে নদীপথ, খাল ও সড়ক যোগাযোগ ব্যবস্থা উন্নত ছিল। একসঙ্গে এই সব কারণ ইংল্যান্ডকে শিল্পবিপ্লবের উপযুক্ত স্থান করে তোলে।''',
  '''voice_script''': '''প্রিয় ছাত্রছাত্রীরা, আজ আমরা জানব ইংল্যান্ডে কেন শিল্পবিপ্লব প্রথম শুরু হয়েছিল। তোমরা কি কখনও ভেবেছো, কেন ইংল্যান্ডেই প্রথম? ফ্রান্স নয়, জার্মানি নয়? এর পেছনে বেশ কয়েকটি কারণ কাজ করেছিল। প্রথম কারণ — ইংল্যান্ডে কয়লা ও লোহার প্রাচুর্য ছিল। শিল্পের জন্য এই দুইটি জিনিস সবচেয়ে জরুরি। কয়লা জ্বালানি হিসেবে কারখানার ইঞ্জিন চালাত, আর লোহা দিয়ে যন্ত্রপাতি ও মেশিন তৈরি হত। দ্বিতীয় কারণ — ইংল্যান্ডের বিস্তৃত উপনিবেশ ছিল। ভারত, আমেরিকা, অস্ট্রেলিয়া, কানাডা — এ সব জায়গা থেকে তুলা, পাট, রেশমের মতো কাঁচামাল খুব সস্তায় আনা যেত। আর সেই কাঁচামাল দিয়ে তৈরি পণ্য আবার সেই উপনিবেশগুলোতে বিক্রি করা যেত। তৃতীয় আরেকটি গুরুত্বপূর্ণ কারণ ছিল কৃষি বিপ্লব। ইংল্যান্ডে সপ্তদশ শতাব্দীতে কৃষি বিপ্লব ও বেষ্টন আইন চালু হয়। এর ফলে ছোট ছোট কৃষকরা তাদের জমি থেকে উচ্ছেদ হয়। তাহলে তারা কোথায় গেল? তারা শহরে চলে এল — কারখানায় কাজ নিতে। এভাবেই কারখানার জন্য সস্তা শ্রমিকের যোগান তৈরি হল। বুঝতে পারছ? চতুর্থ কারণ — ইংল্যান্ডে বাণিজ্য ও দাসব্যবসার মাধ্যমে প্রচুর পুঁজি জমা হয়েছিল। এই পুঁজি দিয়ে কারখানা স্থাপন, যন্ত্রপাতি কেনা, কাঁচামাল আনা সম্ভব হয়। পঞ্চম কারণ — বাষ্পীয় ইঞ্জিন। জেমস ওয়াট ১৭৬৯ সালে বাষ্পীয় ইঞ্জিন উন্নত করেন যা শিল্পবিপ্লবের চালিকাশক্তি হয়ে ওঠে। আর ষষ্ঠ কারণ — রাজনৈতিক স্থিতিশীলতা। ইংল্যান্ডে ইউরোপের অন্যান্য দেশের মতো ঘন ঘন যুদ্ধবিগ্রহ ছিল না। সম্পত্তির নিরাপত্তা ছিল। পুঁজিপতিরা নিশ্চিত ছিল যে তাদের বিনিয়োগ সুরক্ষিত থাকবে। উপরন্তু ইংল্যান্ডের যোগাযোগ ব্যবস্থা উন্নত ছিল — যেমন নদীপথ, খাল ও সড়কপথ মালপত্র পরিবহন সহজ করে তুলেছিল। আরো একটি বিষয় তোমাদের মনে রাখা জরুরি — ইংল্যান্ডের নদীপথ ও সমুদ্রবন্দর ছিল উন্নত। আসলে, দেশের ভেতরে মালপত্র পরিবহন সহজ হতো এবং বাইরের দেশের সঙ্গেও বাণিজ্য করতে সুবিধা হতো। লিভারপুল, ব্রিস্টলের মতো বন্দর শহরগুলি শিল্প বিপ্লবের সময় খুব গুরুত্বপূর্ণ হয়ে ওঠে। সব মিলিয়ে ইংল্যান্ড শিল্পবিপ্লবের জন্য আদর্শ জায়গা ছিল। কয়লা, লোহা, উপনিবেশ, কৃষি বিপ্লব, পুঁজি, বাষ্পীয় ইঞ্জিন, রাজনৈতিক স্থিতিশীলতা ও উন্নত যোগাযোগ — এই সব মিলিয়েই ইংল্যান্ডে প্রথম শিল্পবিপ্লব শুরু হয়। আশা করি তোমরা কারণগুলো ভালোভাবে বুঝতে পেরেছো। মনে রেখো, শুধু একটি কারণে নয় — বরং একাধিক কারণ একসঙ্গে কাজ করায় ইংল্যান্ডে শিল্পবিপ্লব প্রথম শুরু হয়।''',
