  '''name''': '''ইংল্যান্ড ও মহাদেশে শিল্পবিপ্লবের তুলনামূলক পরিচয়''',
  '''order''': 3,
  '''summary''': '''ইংল্যান্ডে শিল্পবিপ্লব শুরু হলেও মহাদেশীয় ইউরোপে তা অপেক্ষাকৃত দেরিতে শুরু হয়। ইংল্যান্ডে রাষ্ট্রীয় হস্তক্ষেপ কম ছিল, বেসরকারি উদ্যোগ বেশি কাজ করেছিল। অন্যদিকে মহাদেশে জার্মানি, ফ্রান্স, বেলজিয়ামে রাষ্ট্রীয় পৃষ্ঠপোষকতা গুরুত্বপূর্ণ ভূমিকা রাখে। বেলজিয়াম ছিল মহাদেশের প্রথম শিল্পায়িত দেশ। ফ্রান্সে ১৮৩০-এর দশকে শিল্পায়ন শুরু হয়, জার্মানিতে ১৮৭১ সালে জাতীয় ঐক্যের পর শিল্পায়ন দ্রুত হয়। ইতালি ও রাশিয়া অপেক্ষাকৃত পিছিয়ে ছিল। ইংল্যান্ডের তুলনায় মহাদেশে কৃষিভিত্তিক অর্থনীতি বেশি দিন টিকে ছিল।''',
  '''voice_script''': '''প্রিয় ছাত্রছাত্রীরা, আজ আমরা জানব ইংল্যান্ড ও ইউরোপের মহাদেশীয় দেশগুলোতে শিল্পবিপ্লবের তুলনামূলক পরিচয়। তোমরা ইতিমধ্যে জানো যে শিল্পবিপ্লব প্রথম ইংল্যান্ডে শুরু হয়েছিল। কিন্তু মহাদেশীয় ইউরোপের দেশগুলোতে কখন এবং কীভাবে শিল্পবিপ্লব এল? আসলে, ইংল্যান্ড আর মহাদেশের মধ্যে বেশ কিছু গুরুত্বপূর্ণ পার্থক্য ছিল। প্রথমত, ইংল্যান্ডে শিল্পবিপ্লব মূলত বেসরকারি উদ্যোগে হয়েছিল। সরকার খুব বেশি হস্তক্ষেপ করেনি। উদ্যোক্তারা নিজেদের পুঁজিতে কারখানা তৈরি করে, নতুন যন্ত্রপাতি উদ্ভাবন করে। কিন্তু মহাদেশে ব্যাপারটা উল্টো! যেমন, জার্মানিতে শিল্পায়নে রাষ্ট্রীয় পৃষ্ঠপোষকতা ছিল অনেক বেশি। সরকার ব্যাংক স্থাপন করে, রেলপথ নির্মাণে অর্থায়ন করে, এমনকি শিল্প প্রতিষ্ঠানগুলোকে সরাসরি ভর্তুকি দিত। দ্বিতীয় পার্থক্য হলো সময়। ইংল্যান্ডে ১৭৬০-এর দশক থেকেই শিল্পবিপ্লব শুরু, কিন্তু মহাদেশে তার অনেক পরে। ফ্রান্সে শুরু হয় ১৮৩০-এর দশকে, আর জার্মানিতে শুরু হয় ১৮৭১ সালে জাতীয় ঐক্যের পর। বেলজিয়াম ছিল ব্যতিক্রম — ইংল্যান্ডের ঠিক পরেই মহাদেশের মধ্যে প্রথম শিল্পায়িত দেশ। ১৮৩০ সালে স্বাধীনতা লাভের পর বেলজিয়াম দ্রুত শিল্পায়িত হয়। মনে রেখো, বেলজিয়ামের কয়লা ও লোহার খনি এবং বন্দরনগরী এন্টওয়ার্প এর শিল্পায়নে গুরুত্বপূর্ণ ভূমিকা রাখে। তৃতীয় পার্থক্য — ইংল্যান্ডে কৃষি বিপ্লব আগেই হয়ে গিয়েছিল, কৃষকরা জমি থেকে উচ্ছেদ হয়ে শহরে কারখানায় কাজ নিতে বাধ্য হয়েছিল। কিন্তু মহাদেশের দেশগুলোতে, বিশেষ করে ফ্রান্সে, কৃষি বিপ্লব খুব ধীরে হয়। ফলে সেখানে কারখানার জন্য সস্তা শ্রমিক পাওয়া কঠিন ছিল। চতুর্থ পার্থক্য — ইংল্যান্ডের উপনিবেশ ছিল বিশাল, যা কাঁচামাল ও বাজার সরবরাহ করত। মহাদেশের দেশগুলোর হাতে তেমন উপনিবেশ ছিল না — জার্মানি ও ইতালি তো ঐক্যের আগে উপনিবেশ পায়ইনি। বেলজিয়াম পরে কঙ্গো উপনিবেশ পায়। ইংল্যান্ডে রেলপথ ও খালের মাধ্যমে যোগাযোগ ব্যবস্থা উন্নত ছিল। মহাদেশে রেলপথ নির্মাণে ইংল্যান্ডের সাহায্য নেওয়া হয়। জার্মানিতে প্রথম রেলপথ চালু হয় ১৮৩৫ সালে নুরেমবার্গ ও ফুর্থের মধ্যে। বুঝতে পারছ? ইংল্যান্ড আর মহাদেশে শিল্পবিপ্লবের পথ ছিল ভিন্ন। তবু শেষ পর্যন্ত শিল্পায়ন সারা ইউরোপে ছড়িয়ে পড়ে। আশা করি তোমরা এই তুলনামূলক ধারণা পেয়েছ। মনে রেখো, ইংল্যান্ড ছিল পথিকৃৎ, আর জার্মানি ও ফ্রান্স দ্রুত ইংল্যান্ডকে অনুসরণ করে এবং কিছু ক্ষেত্রে ইংল্যান্ডকেও ছাড়িয়ে যায়, যেমন জার্মানির রাসায়নিক ও বৈদ্যুতিক শিল্প। এখন আমরা আরেকটি গুরুত্বপূর্ণ বিষয়ে আসি — শিল্পবিপ্লবের প্রভাব। কি প্রশ্ন থাকলে?''',
