  '''real_life_example''': '''বাংলাদেশের তৈরি পোশাক শিল্পের কথা ভাবো। সরকার বিভিন্ন নীতি ও অবকাঠামো দিয়ে সাহায্য করে — এটি মহাদেশীয় শিল্পায়নের মতো। অন্যদিকে একটি ছোট উদ্যোক্তা নিজের পুঁজিতে কারখানা খুললে তা ইংল্যান্ডের বেসরকারি উদ্যোগের মতো।''',
