  '''order''': 4,
  '''summary''': '''শিল্পবিপ্লব সমাজ, রাজনীতি ও অর্থনীতিতে গভীর প্রভাব ফেলে। সমাজে পুঁজিপতি ও শ্রমিক শ্রেণির দ্বন্দ্ব তৈরি হয় এবং নগরায়ণ দ্রুত বাড়ে। রাজনীতিতে উদারনীতিবাদ, সমাজতন্ত্র ও ট্রেড ইউনিয়নের উদ্ভব ঘটে। ভোটাধিকার আন্দোলন ও শ্রমিক আইন প্রণয়ন হয়। অর্থনীতিতে পুঁজিবাদী ব্যবস্থা সুসংহত হয়, ব্যাংক ও বীমা প্রতিষ্ঠান গড়ে ওঠে। বিশ্ব বাণিজ্য সম্প্রসারিত হয় এবং আন্তর্জাতিক অর্থনীতি তৈরি হয়। শিল্পবিপ্লব কেবল প্রযুক্তিগত নয়, একটি সামগ্রিক সামাজিক বিপ্লব ছিল যা আধুনিক বিশ্বের ভিত্তি স্থাপন করে।''',
  '''voice_script''': '''প্রিয় ছাত্রছাত্রীরা, আজ আমরা আলোচনা করব শিল্পবিপ্লব কীভাবে সমাজ, রাজনীতি ও অর্থনীতিকে বদলে দিয়েছিল। তোমরা নিশ্চয়ই জানো শিল্পবিপ্লব কেবল কলকারখানা ও যন্ত্রের ব্যাপার ছিল না — এটি ছিল এক বিশাল সামাজিক বিপ্লব। আগে সমাজ ছিল প্রধানত গ্রামভিত্তিক। মানুষ কৃষিকাজ ও কুটিরশিল্প করে গ্রামেই বসবাস করত। কিন্তু শিল্পবিপ্লবের পর সব বদলে গেল। কারখানা গড়ে উঠল শহরে, আর মানুষ কাজের সন্ধানে শহরে আসতে শুরু করল। নগরায়ণ শুরু হল। যেমন, ইংল্যান্ডের ম্যানচেস্টার শহর — ১৭৬০ সালে যেখানে মাত্র ১৭,০০০ মানুষ ছিল, ১৮৫০ সালে তা বেড়ে ৩,০০,০০০ হয়! এই দ্রুত নগরায়ণের ফলে শহরগুলোতে নানা সমস্যা দেখা দেয় — বস্তি, অপরিচ্ছন্নতা, রোগব্যাধি। দ্বিতীয় গুরুত্বপূর্ণ পরিবর্তন হলো সমাজে নতুন দুটি শ্রেণির উদ্ভব — পুঁজিপতি বা বুর্জোয়া শ্রেণি আর শ্রমিক বা প্রলেতারিয়েত শ্রেণি। পুঁজিপতিরা কারখানার মালিক, আর শ্রমিকরা মজুরির বিনিময়ে কাজ করে। এই দুই শ্রেণির মধ্যে দ্বন্দ্ব শুরু হয়। শ্রমিকরা বেশি মজুরি, কম কাজের সময় ও ভালো কাজের পরিবেশ চায়, কিন্তু মালিকরা বেশি মুনাফা চায়। বুঝতে পারছ? এই দ্বন্দ্ব থেকেই জন্ম নেয় ট্রেড ইউনিয়ন বা শ্রমিক সংগঠন। শ্রমিকরা সংগঠিত হয়ে নিজেদের অধিকার আদায়ের জন্য আন্দোলন শুরু করে। লুডাইট আন্দোলন, চার্টিস্ট আন্দোলন — এগুলি এর উদাহরণ। রাজনীতিতে শিল্পবিপ্লবের আরেকটি গুরুত্বপূর্ণ প্রভাব ছিল উদারনীতিবাদ ও সমাজতন্ত্রের উত্থান। উদারনীতিবাদী চিন্তাবিদ যেমন জন স্টুয়ার্ট মিল ব্যক্তিস্বাধীনতা ও মুক্ত বাণিজ্যের পক্ষে ছিলেন। অন্যদিকে কার্ল মার্কস ও ফ্রিডরিখ এঙ্গেলস সমাজতন্ত্রের তত্ত্ব দেন। মার্কস লিখেছিলেন "দাস ক্যাপিটাল" এবং তিনি মনে করতেন পুঁজিবাদ ধ্বংস হবে এবং সমাজতন্ত্র প্রতিষ্ঠিত হবে। অর্থনীতির দিকে তাকালে দেখা যায়, শিল্পবিপ্লব পুঁজিবাদী অর্থনীতিকে সুসংহত করে। ব্যাংক, স্টক এক্সচেঞ্জ, বীমা কোম্পানি — এসব প্রতিষ্ঠান গড়ে ওঠে। বিশ্ব বাণিজ্য বাড়ে। ইংল্যান্ড "বিশ্বের কারখানা" হয়ে ওঠে। মনে রেখো, শিল্পবিপ্লবের ফলে অর্থনীতিতে চক্রাকার মন্দা শুরু হয়। ১৮১৯, ১৮২৫, ১৮৩৭, ১৮৪৭ সালে অর্থনৈতিক মন্দা দেখা দেয়। আরেকটি গুরুত্বপূর্ণ দিক হলো শিশুশ্রমের সমস্যা। কারখানায় ছোট ছোট শিশুরা দিনরাত কাজ করত, তাদের বিদ্যালয়ে যাওয়ার সুযোগ ছিল না। এই অবস্থার বিরুদ্ধেও আন্দোলন গড়ে ওঠে এবং ১৮৩৩ সালে প্রথম কারখানা আইন পাস হয় যা শিশুশ্রমের সময়সীমা নির্ধারণ করে। আইন প্রণয়নে পার্লামেন্টে দীর্ঘ বিতর্ক হয় এবং ধীরে ধীরে শ্রমিক অধিকার স্বীকৃত হতে থাকে। আশা করি তোমরা এই গুরুত্বপূর্ণ সামাজিক পরিবর্তনগুলো বুঝতে পেরেছো। এখন কি কোনো প্রশ্ন আছে?''',
