  '''summary''': '''শিল্পবিপ্লবের ফলে সৃষ্ট শিল্প সমাজের বিভিন্ন সমালোচনা দেখা দেয়। প্রথমত, মানবতাবাদী সমালোচকরা শ্রমিকের শোষণ ও অমানবিক পরিস্থিতির নিন্দা করেন। দ্বিতীয়ত, রোমান্টিক সমালোচকরা প্রকৃতি ও ঐতিহ্য ধ্বংসের জন্য শিল্পায়নকে দায়ী করেন। তৃতীয়ত, সমাজতান্ত্রিক সমালোচকরা পুঁজিবাদী শোষণ ও সম্পদের অসম বণ্টনের সমালোচনা করেন। চার্লস ডিকেন্সের উপন্যাস, উইলিয়াম ব্লেকের কবিতা, মার্কসের তত্ত্ব এবং রাসকিনের শিল্পসমালোচনা — সবই শিল্প সমাজের বিভিন্ন সমালোচনা প্রকাশ করে।''',
  '''voice_script''': '''প্রিয় ছাত্রছাত্রীরা, আজ আমরা জানব শিল্প সমাজের সমালোচনার বিভিন্ন দিক সম্পর্কে। তোমরা হয়তো ভাবছ, শিল্পবিপ্লব কীভাবে সমালোচিত হতে পারে? আসলে শিল্পবিপ্লব যেমন উন্নতি এনেছিল, তেমনি এর অনেক নেতিবাচক দিকও ছিল। সেগুলো নিয়েই সমালোচনা শুরু হয়। প্রথম ধরনের সমালোচনা — মানবতাবাদী সমালোচনা। লেখক চার্লস ডিকেন্স তাঁর "অলিভার টুইস্ট", "হার্ড টাইমস" উপন্যাসে শ্রমিক ও শিশুশ্রমিকের দুর্দশা ফুটিয়ে তোলেন। কারখানায় ৬-৭ বছরের শিশুরা দিনে ১৪-১৬ ঘণ্টা কাজ করত। তাদের অল্প মজুরি দেওয়া হত, খেতে দেওয়া হত না। কয়লাখনিতে শিশুরা অন্ধকারে কাজ করত। ডিকেন্স এসবের কঠোর সমালোচনা করেন। দ্বিতীয় সমালোচনা — রোমান্টিক সমালোচনা। কবি উইলিয়াম ব্লেক ইংল্যান্ডের "অন্ধকার স্যাটানিক মিল" বা কলকারখানার বিরুদ্ধে লিখেছেন। তিনি বলেন শিল্পায়ন মানুষের আত্মা ও প্রকৃতি উভয়কেই ধ্বংস করছে। তাঁর "দ্য টাইগার" ও "লন্ডন" কবিতায় এসবের প্রতিফলন আছে। তৃতীয় সমালোচনা — সমাজতান্ত্রিক সমালোচনা। কার্ল মার্কস ও এঙ্গেলস পুঁজিবাদী শিল্প সমাজের বিরুদ্ধে কঠোর সমালোচনা করেন। তাঁদের মতে পুঁজিপতিরা শ্রমিকের উদ্বৃত্ত মূল্য আত্মসাৎ করে। শ্রমিকরা যা উৎপাদন করে তার সম্পূর্ণ মূল্য পায় না। বুঝতে পারছ, মার্কসের উদ্বৃত্ত মূল্য তত্ত্ব শিল্প সমাজের অর্থনৈতিক সমালোচনার মূলে রয়েছে। তাঁরা বলেন পুঁজিবাদী সমাজে সম্পদের অসম বণ্টন অনিবার্য। চতুর্থ সমালোচনা — নান্দনিক ও সাংস্কৃতিক সমালোচনা। জন রাসকিন ও উইলিয়াম মরিস শিল্পের যান্ত্রিকতা ও সৌন্দর্যহীনতার সমালোচনা করেন। রাসকিন বলেন শিল্পায়ন মানবসৃষ্ট সৌন্দর্য ধ্বংস করছে। মরিস শিল্প ও কারুকার্যের সমন্বয়ের পক্ষে মত দেন। আরও একটি গুরুত্বপূর্ণ সমালোচনা ছিল ধর্মীয় ও নৈতিক দৃষ্টিকোণ থেকে। অনেক ধর্মীয় নেতা মনে করতেন শিল্পায়ন মানুষের নৈতিক মূল্যবোধ ধ্বংস করছে। পরিবারভিত্তিক সমাজ ভেঙে যাচ্ছে, নগরে অনৈতিকতা ও অপরাধ বাড়ছে। জন ওয়েসলির মতো মেথডিস্ট নেতারাও এই গভীর উদ্বেগ প্রকাশ করেন এবং শ্রমিকদের নৈতিক উন্নয়নে গুরুত্বপূর্ণ কাজ করেন। মনে রেখো, এসব সমালোচনার কারণেই পরে সমাজ সংস্কারমূলক আইন ও আন্দোলন শুরু হয়। যেমন, শিশুশ্রম নিষিদ্ধ হয়, কারখানা আইন পাস হয়, ট্রেড ইউনিয়ন বৈধতা পায়। সমালোচকদের এই ভূমিকা ইতিহাসের গতিপথ বদলে দিয়েছিল। আশা করি তোমরা শিল্প সমাজের সমালোচনার বিভিন্ন দিক ভালোভাবে বুঝতে পেরেছো। কোনো প্রশ্ন থাকলে জিজ্ঞাসা করো।''',
