  '''order''': 6,
  '''summary''': '''শিল্পবিপ্লবের ফলে ইংল্যান্ড ও অন্যান্য শিল্পোন্নত দেশে বিপুল পরিমাণ পণ্য উৎপাদিত হতে থাকে। এই পণ্য বিক্রির জন্য প্রয়োজন হয় বাজার। অন্যদিকে কারখানার কাঁচামাল যেমন তুলা, পাট, রেশম, লোহা প্রয়োজন হয়। শিল্পোন্নত দেশগুলো এই প্রয়োজন মেটানোর জন্য এশিয়া, আফ্রিকা ও আমেরিকায় উপনিবেশ স্থাপন করে। উপনিবেশ থেকে সস্তায় কাঁচামাল আনা হত এবং তৈরি পণ্য সেখানে বেশি দামে বিক্রি করা হত। এই ব্যবস্থাই উপনিবেশিক অর্থনীতির জন্ম দেয় এবং শিল্পবিপ্লব ও উপনিবেশবাদ পরস্পর সম্পর্কিত হয়ে ওঠে।''',
  '''voice_script''': '''প্রিয় ছাত্রছাত্রীরা, আজ আমরা জানব শিল্পবিপ্লব কীভাবে উপনিবেশের জন্ম দিয়েছিল। তোমরা কি কখনও ভেবেছো, কেন ইউরোপীয় দেশগুলো এশিয়া, আফ্রিকা ও আমেরিকায় উপনিবেশ স্থাপন করেছিল? আসলে এর মূল কারণ শিল্পবিপ্লব। শিল্পবিপ্লবের ফলে ইংল্যান্ড, ফ্রান্স, জার্মানি, বেলজিয়ামের মতো দেশে বিপুল পরিমাণ পণ্য উৎপাদিত হতে শুরু করে। এখন প্রশ্ন হলো — এই পণ্য কোথায় বিক্রি হবে? ইংল্যান্ডের নিজের বাজার তো সীমিত। তাহলে? দরকার ছিল বড় বাজার। আরও দরকার ছিল কাঁচামাল — তুলা, পাট, রেশম, লোহা, কয়লা — এসবের সস্তা ও নিশ্চিত সরবরাহ। এই প্রয়োজন থেকেই উপনিবেশের জন্ম। উদাহরণ দিয়ে বুঝি — ইংল্যান্ডে বস্ত্রশিল্পের জন্য তুলা প্রয়োজন। ভারত, মিশর, আমেরিকা থেকে তুলা আনা হত। কিন্তু তুলার বিনিময়ে ইংল্যান্ড কী দিত? কিছুই না, বা খুব কম। বরং ইংল্যান্ড তার তৈরি কাপড় ভারতে বিক্রি করত আর ভারতীয় কুটিরশিল্প ধ্বংস করে দিত। মনে রেখো, বাংলার বস্ত্রশিল্প ধ্বংসের পেছনে এই শিল্পবিপ্লবের চাহিদাই কাজ করেছিল। ইংল্যান্ডের তৈরি কাপড় ভারতের বাজারে এত সস্তায় বিক্রি হত যে ভারতীয় তাঁতিরা টিকতে পারেনি। ভারত থেকে কাঁচামাল ইংল্যান্ডে যেত, আর ইংল্যান্ড থেকে তৈরি পণ্য ভারতে আসত — এটি ছিল একমুখী বাণিজ্য ব্যবস্থা যা ভারতের অর্থনীতিকে ধ্বংস করে দেয়। বুঝতে পারছ? এখন শুধু ইংল্যান্ড নয়, ফ্রান্স, জার্মানি, বেলজিয়াম, ইতালি — সবাই উপনিবেশের পেছনে ছোটে। কারণ প্রতিটি শিল্পোন্নত দেশের প্রয়োজন — কাঁচামাল, বাজার ও সস্তা শ্রমিক। যেমন, যেমন শিল্পবিপ্লবের সময় কাঁচামাল চাহিদা আরও বাড়তে থাকে। এছাড়া ইউরোপের দেশগুলোর মধ্যে প্রতিযোগিতা শুরু হয় — কে বেশি উপনিবেশ দখল করতে পারে। এই প্রতিযোগিতাই পরবর্তীতে প্রথম বিশ্বযুদ্ধের অন্যতম কারণ। আসলে শিল্পবিপ্লব আর উপনিবেশবাদ একে অপরের পরিপূরক। শিল্পবিপ্লব যেমন উপনিবেশ তৈরি করে, উপনিবেশ আবার শিল্পায়নকে আরও ত্বরান্বিত করে। ফলে একবার শুরু হলে এই চক্র চলতেই থাকে। অন্যদিকে, শিল্পবিপ্লবের ফলে ইউরোপীয় দেশগুলোর মধ্যে সামরিক শক্তির প্রতিযোগিতা শুরু হয়। উন্নত অস্ত্র, নৌবাহিনী আর রেলপথ — সবই উপনিবেশ দখল ও নিয়ন্ত্রণে কাজে লাগে। আশা করি তোমরা শিল্পবিপ্লব ও উপনিবেশের সম্পর্ক বুঝতে পেরেছো। মনে রেখো, শিল্পবিপ্লব কেবল কারখানার বিপ্লব ছিল না, এটি উপনিবেশবাদ ও সাম্রাজ্যবাদেরও জন্ম দিয়েছিল। এখন আমরা পরবর্তী টপিকে যাব, কি বলো?''',
