  '''name''': '''ইউরোপের বাইরে উপনিবেশ গঠনকারী দেশসমূহ''',
  '''order''': 7,
  '''summary''': '''উনবিংশ শতাব্দীতে ইউরোপের কয়েকটি প্রধান শক্তি এশিয়া, আফ্রিকা ও আমেরিকায় উপনিবেশ গঠন করে। ব্রিটিশ সাম্রাজ্য ছিল সর্ববৃহৎ — ভারত, বর্মা, অস্ট্রেলিয়া, কানাডা, দক্ষিণ আফ্রিকা, মিশরসহ বিস্তৃত অঞ্চল জুড়ে। ফ্রান্সের উপনিবেশ ছিল আলজেরিয়া, ভিয়েতনাম, কম্বোডিয়া, লাওস ও পশ্চিম আফ্রিকায়। জার্মানি দেরিতে উপনিবেশ পেলেও নামিবিয়া, ক্যামেরুন, পূর্ব আফ্রিকায় নিজেদের সাম্রাজ্য গড়ে। বেলজিয়াম কঙ্গো দখল করে। ইতালি লিবিয়া ও ইথিওপিয়ায় হামলা চালায়। পর্তুগাল অ্যাঙ্গোলা ও মোজাম্বিক ধরে রাখে। এভাবে ইউরোপের শক্তিগুলো সারা বিশ্বকে ভাগ করে নেয়।''',
  '''voice_script''': '''প্রিয় ছাত্রছাত্রীরা, আজ আমরা জানব ইউরোপের বাইরে কোন কোন দেশ উপনিবেশ গঠন করেছিল। তোমরা নিশ্চয়ই জানো উনবিংশ শতাব্দীকে "উপনিবেশের যুগ" বলা হয়। কারণ এই সময় ইউরোপের বড় বড় শক্তি সারা বিশ্বে উপনিবেশ তৈরি করে। প্রথম ও প্রধান শক্তি হলো ব্রিটিশ সাম্রাজ্য। ব্রিটেনের উপনিবেশ এত বিস্তৃত ছিল যে বলা হত "ব্রিটিশ সাম্রাজ্যে সূর্য কখনও অস্ত যায় না"। ব্রিটিশ উপনিবেশের মধ্যে ছিল ভারত — সবচেয়ে বড় ও গুরুত্বপূর্ণ, বর্মা, সিংহল, মালয়, হংকং, অস্ট্রেলিয়া, কানাডা, দক্ষিণ আফ্রিকা, মিশর, সুদান, নাইজেরিয়া, কেনিয়া — আসলে গোটা বিশ্বেই ব্রিটিশ উপনিবেশ ছড়িয়ে ছিল। যেমন, ব্রিটেনের জন্য ভারত ছিল সবচেয়ে গুরুত্বপূর্ণ উপনিবেশ। ভারত থেকে তুলা, পাট, নীল, চা, রেশম — সবকিছুই যেত ইংল্যান্ডে। দ্বিতীয় শক্তি হলো ফ্রান্স। ফ্রান্সের উপনিবেশ উত্তর ও পশ্চিম আফ্রিকায় বিস্তৃত ছিল — আলজেরিয়া, মরক্কো, তিউনিসিয়া, সেনেগাল, আইভরি কোস্ট। এশিয়ায় ফ্রান্সের উপনিবেশ ছিল ইন্দোচীন — ভিয়েতনাম, কম্বোডিয়া, লাওস। মনে রেখো, ফ্রান্স-ব্রিটেনের মধ্যে উপনিবেশ নিয়ে প্রতিদ্বন্দ্বিতা ছিল তীব্র। তৃতীয় শক্তি জার্মানি। জার্মানি ইউরোপে দেরিতে শিল্পায়িত হলেও উপনিবেশ পেতে পিছিয়ে ছিল না। তাদের উপনিবেশ ছিল পূর্ব আফ্রিকা, নামিবিয়া, ক্যামেরুন, টোগো। প্রথম বিশ্বযুদ্ধের আগে জার্মানি দ্রুত উপনিবেশ সম্প্রসারণ করে। চতুর্থ শক্তি হলো বেলজিয়াম। বেলজিয়ামের রাজা দ্বিতীয় লিওপোল্ড নিজ ব্যক্তিগত সম্পত্তি হিসেবে কঙ্গো দখল করেন। কঙ্গোতে অমানুষিক নির্যাতন চালানো হয়। পঞ্চম শক্তি ইতালি। ইতালি লিবিয়া ও ইথিওপিয়া দখলের চেষ্টা করে কিন্তু ইথিওপিয়ায় পরাজিত হয়। ষষ্ঠ ও সপ্তম শক্তি হলো পর্তুগাল ও স্পেন। পর্তুগাল অ্যাঙ্গোলা ও মোজাম্বিক ধরে রাখে। স্পেনের ফিলিপাইন ১৮৯৮ সালে আমেরিকার কাছে চলে যায়। বুঝতে পারছ, ১৯১৪ সালের মধ্যে সমগ্র আফ্রিকা ও এশিয়ার অধিকাংশই ইউরোপীয় উপনিবেশে পরিণত হয়। আরেকটি গুরুত্বপূর্ণ বিষয় হলো বার্লিন সম্মেলন ১৮৮৪-৮৫, যেখানে ইউরোপীয় শক্তিগুলো আফ্রিকা ভাগ করে নেয়। এই সম্মেলনে অংশগ্রহণকারী দেশগুলোর মধ্যে জার্মানির চ্যান্সেলর বিসমার্ক গুরুত্বপূর্ণ ভূমিকা পালন করেন। বার্লিন সম্মেলনে আফ্রিকার মানচিত্র পুনর্নির্মাণ করা হয় এবং দখলদারিত্বের নিয়ম নির্ধারণ করা হয় — কোনো দেশ কোনো অঞ্চল দখল করলে তা অন্যান্য শক্তিকে জানাতে হবে। আর উপনিবেশগুলোর কী পরিণতি হয়েছিল? স্থানীয় জনগণের উপর অত্যাচার, সম্পদ লুণ্ঠন ও সংস্কৃতি ধ্বংস — এই ছিল উপনিবেশের অন্ধকার দিক। উপনিবেশগুলোর সম্পদ ইউরোপের শিল্পায়নে ব্যবহৃত হলেও সেখানকার স্থানীয় মানুষ পায়নি কোনো সুবিধা, বরং তারা হারিয়েছে নিজস্ব ভূমি ও সম্পদ। আশা করি তোমরা এই দেশগুলোর নাম ও উপনিবেশ মনে রাখতে পেরেছো। এখন প্রশ্ন থাকলে জিজ্ঞাসা করো। মনে থাকে তো সঠিক উত্তর দিতে পারবে?''',
  '''simple_breakdown''':   [
