  '''order''': 8,
  '''summary''': '''উনবিংশ শতাব্দীর শেষভাগে ইউরোপীয় শক্তিগুলোর মধ্যে উপনিবেশ নিয়ে প্রতিদ্বন্দ্বিতা তীব্র হয়। ব্রিটেন ও ফ্রান্সের মধ্যে ফাশোদা ঘটনা, ব্রিটেন ও জার্মানির মধ্যে নৌ প্রতিযোগিতা, রাশিয়া ও ব্রিটেনের মধ্যে মধ্য এশিয়ায় গ্রেট গেম — সবই এই প্রতিদ্বন্দ্বিতার অংশ। ১৮৭০-এর পর থেকে "নতুন সাম্রাজ্যবাদ" নামে এক পর্যায় শুরু হয়, যেখানে ইউরোপের শক্তিগুলো এশিয়া ও আফ্রিকা দখলে মেতে ওঠে। এই প্রতিদ্বন্দ্বিতাই ইউরোপকে দুটি শিবিরে ভাগ করে এবং শেষ পর্যন্ত প্রথম বিশ্বযুদ্ধের পথ প্রশস্ত করে। বার্লিন সম্মেলন আফ্রিকা বিভাজনের নিয়মনীতি ঠিক করে।''',
  '''voice_script''': '''প্রিয় ছাত্রছাত্রীরা, আজ আমরা আলোচনা করব ঔপনিবেশিক প্রতিদ্বন্দ্বিতা ও ইউরোপীয় সাম্রাজ্যবাদ সম্পর্কে। তোমরা আগের ক্লাসে জেনেছ কিভাবে ইউরোপীয় দেশগুলো এশিয়া ও আফ্রিকায় উপনিবেশ তৈরি করে। কিন্তু প্রশ্ন হলো — এই সব দেশ কি শান্তিপূর্ণভাবে উপনিবেশ ভাগ করে নিয়েছিল? একদমই না। আসলে উপনিবেশ নিয়ে ইউরোপীয় শক্তিগুলোর মধ্যে তীব্র প্রতিদ্বন্দ্বিতা ছিল। এই প্রতিদ্বন্দ্বিতাকে বলা হয় "ঔপনিবেশিক প্রতিদ্বন্দ্বিতা"। ১৮৭০ সালের পরে এই প্রতিদ্বন্দ্বিতা আরও তীব্র হয় এবং একে বলা হয় "নতুন সাম্রাজ্যবাদ"। আগে ষোড়শ-সপ্তদশ শতাব্দীতে উপনিবেশ ছিল মূলত স্পেন ও পর্তুগালের। কিন্তু ১৮৭০ সালের পর শিল্পোন্নত দেশগুলো — ব্রিটেন, ফ্রান্স, জার্মানি, বেলজিয়াম, ইতালি — সবাই উপনিবেশের পেছনে ছোটা শুরু করে। যেমন, ফ্রান্স ও ব্রিটেনের মধ্যে উপনিবেশ নিয়ে টানাপোড়েন ছিল পুরনো। ১৮৯৮ সালে সুদানের ফাশোদায় এই দুই শক্তি প্রায় যুদ্ধের মুখোমুখি হয়েছিল — একে বলে ফাশোদা ঘটনা। শেষ পর্যন্ত ফ্রান্স পিছু হটে। এই প্রতিদ্বন্দ্বিতার আরেকটি দিক হলো ব্রিটেন ও জার্মানির নৌ প্রতিযোগিতা। জার্মানির কাইজার দ্বিতীয় উইলহেলম একটি শক্তিশালী নৌবাহিনী তৈরি করতে চেয়েছিলেন, যা ব্রিটেনের জন্য হুমকি ছিল। ব্রিটেন তার নৌ শক্তি ধরে রাখতে ড্রেডনট শ্রেণির যুদ্ধজাহাজ তৈরি করে। আর একটি গুরুত্বপূর্ণ প্রতিদ্বন্দ্বিতা হলো মধ্য এশিয়ায় ব্রিটেন ও রাশিয়ার মধ্যে "গ্রেট গেম"। ব্রিটেন ভারত রক্ষার জন্য রুশ সম্প্রসারণ ঠেকাতে চেয়েছিল। অন্যদিকে ইউরোপের মধ্যে সাম্রাজ্যবাদী প্রতিযোগিতা ইউরোপকে দুটি শিবিরে ভাগ করে — ট্রিপল অ্যালায়েন্স ও ট্রিপল এনতেন্ত। মনে রেখো, এই দুই জোটের সৃষ্টিই প্রথম বিশ্বযুদ্ধের প্রধান কারণ। ১৮৮২ সালে জার্মানি, অস্ট্রিয়া-হাঙ্গেরি ও ইতালি মিলে ট্রিপল অ্যালায়েন্স গঠন করে। জবাবে ১৯০৭ সালের মধ্যে ফ্রান্স, রাশিয়া ও ব্রিটেন মিলে ট্রিপল এনতেন্ত গঠন করে। ১৯০৪ সালে ব্রিটেন ও ফ্রান্সের মধ্যে এনতেন্ত কর্ডিয়াল চুক্তি হয়। ১৯০৭ সালে ব্রিটেন ও রাশিয়ার মধ্যে অ্যাংলো-রাশিয়ান কনভেনশন হয়। এভাবে ইউরোপ দুটি বিরোধী সামরিক জোটে বিভক্ত হয়। বুঝতে পারছ? উপনিবেশ প্রতিযোগিতা কেবল আফ্রিকা-এশিয়াতেই সীমাবদ্ধ ছিল না — এটি সমগ্র ইউরোপকেও বিভক্ত করেছিল। আরেকটি গুরুত্বপূর্ণ ঘটনা হলো মরোক্কো সংকট (১৯০৫ ও ১৯১১)। জার্মানি মরোক্কোতে ফরাসি আধিপত্য চ্যালেঞ্জ করে এবং দুইবার ইউরোপ যুদ্ধের দ্বারপ্রান্তে পৌঁছে যায়। এই সংকটগুলো জার্মানি-ফ্রান্স ও জার্মানি-ব্রিটেনের মধ্যে সম্পর্ক আরও খারাপ করে। আশা করি তোমরা ঔপনিবেশিক প্রতিদ্বন্দ্বিতা ও সাম্রাজ্যবাদের সম্পর্ক বুঝতে পেরেছো। কোনো প্রশ্ন থাকলে?''',
