  '''name''': '''সাম্রাজ্যবাদী শক্তির সংঘাত: প্রথম বিশ্বযুদ্ধ (শুরু পর্যন্ত)''',
  '''order''': 9,
  '''summary''': '''প্রথম বিশ্বযুদ্ধের মূল কারণ ছিল সাম্রাজ্যবাদী প্রতিদ্বন্দ্বিতা, জোট বিভাজন, অস্ত্র প্রতিযোগিতা ও বলকান সংকট। ১৯১৪ সালের ২৮ জুন অস্ট্রিয়ার যুবরাজ ফ্রান্স ফার্ডিনান্ড নিহত হলে যুদ্ধ শুরু হয়। অস্ট্রিয়া সার্বিয়াকে আল্টিমেটাম দেয়। রাশিয়া সার্বিয়ার পক্ষে। জার্মানি রাশিয়ার বিরুদ্ধে যুদ্ধ ঘোষণা করে। জার্মানি বেলজিয়াম আক্রমণ করলে ব্রিটেন যুদ্ধে যোগ দেয়। শ্লিফেন পরিকল্পনা অনুযায়ী জার্মানি ফ্রান্সে দ্রুত আক্রমণ চায়। মার্নের যুদ্ধে জার্মান অগ্রগতি থামে। পশ্চিম রণাঙ্গনে স্থিতিশীল যুদ্ধ শুরু হয়। উপনিবেশ প্রতিযোগিতার চূড়ান্ত পরিণতি ছিল এই বিশ্বযুদ্ধ।''',
  '''voice_script''': '''প্রিয় ছাত্রছাত্রীরা, আজ আমরা আলোচনা করব সাম্রাজ্যবাদী শক্তির সংঘাত ও প্রথম বিশ্বযুদ্ধের শুরু পর্যন্ত ঘটনা। তোমরা আগের ক্লাসে জেনেছ কীভাবে ঔপনিবেশিক প্রতিদ্বন্দ্বিতা ইউরোপকে দুটি জোটে ভাগ করেছিল। এখন আমরা দেখব কীভাবে সেই প্রতিদ্বন্দ্বিতা বিশ্বযুদ্ধে রূপ নেয়। প্রথম বিশ্বযুদ্ধের তাৎক্ষণিক কারণ ছিল ১৯১৪ সালের ২৮ জুন অস্ট্রিয়া-হাঙ্গেরির যুবরাজ আর্চডিউক ফ্রান্স ফার্ডিনান্ডের হত্যা। তাকে হত্যা করেছিল একজন সার্বিয়ান জাতীয়তাবাদী — গ্যাভরিলো প্রিন্সিপ। এই হত্যাকাণ্ড ঘটেছিল বসনিয়ার সারাজেভো শহরে। তারপর যা ঘটল তা দ্রুতগতিতে যুদ্ধের দিকে এগিয়ে যায়। অস্ট্রিয়া-হাঙ্গেরি সার্বিয়াকে একটি কঠোর আল্টিমেটাম দেয়। সার্বিয়া সব শর্ত মেনে নেয়নি। এরপর অস্ট্রিয়া সার্বিয়ার বিরুদ্ধে যুদ্ধ ঘোষণা করে। তখন জোট বাধ্যবাধকতা কার্যকর হয়। রাশিয়া সার্বিয়ার পক্ষে যোগ দেয়। জার্মানি, অস্ট্রিয়ার মিত্র হয়ে রাশিয়ার বিরুদ্ধে যুদ্ধ ঘোষণা করে। জার্মানি তখন শ্লিফেন পরিকল্পনা অনুযায়ী ফ্রান্স আক্রমণের জন্য বেলজিয়ামের মধ্য দিয়ে অগ্রসর হয়। কিন্তু বেলজিয়াম ছিল নিরপেক্ষ দেশ। জার্মানি বেলজিয়াম আক্রমণ করলে ব্রিটেন বেলজিয়ামের নিরপেক্ষতা রক্ষার অজুহাতে জার্মানির বিরুদ্ধে যুদ্ধ ঘোষণা করে। মনে রেখো, ব্রিটেন আসলে জার্মানিকে ইউরোপে শক্তিশালী হতে দিতে চায়নি। পশ্চিম রণাঙ্গনে জার্মান অগ্রগতি থামে মার্নের যুদ্ধে (সেপ্টেম্বর ১৯১৪)। এরপর পশ্চিম রণাঙ্গনে স্থিতিশীল যুদ্ধ শুরু হয় — পরিখা যুদ্ধ। বুঝতে পারছ? উপনিবেশ ও সাম্রাজ্যবাদী প্রতিযোগিতার ফলেই এই বিশ্বযুদ্ধ। উপনিবেশসমূহ থেকেও সৈন্য ও সম্পদ এল। যেমন, ভারত থেকে ব্রিটিশ সেনাবাহিনীতে লক্ষ লক্ষ সৈন্য যোগ দেয়। আফ্রিকার বিভিন্ন উপনিবেশ থেকেও সৈন্য আনা হয়। প্রথম বিশ্বযুদ্ধ ছিল সত্যিই একটি বিশ্বযুদ্ধ — শুধু ইউরোপ নয়, সমগ্র বিশ্ব এর সঙ্গে জড়িত ছিল। আসলে, প্রথম বিশ্বযুদ্ধের গভীর কারণগুলির মধ্যে ছিল সাম্রাজ্যবাদ, জাতীয়তাবাদ, সামরিকবাদ ও জোট ব্যবস্থা। আর তাৎক্ষণিক কারণ ছিল যুবরাজ হত্যা। পূর্ব রণাঙ্গনে রুশ সেনাবাহিনী জার্মানি ও অস্ট্রিয়ার বিরুদ্ধে লড়াই করে। টানেনবার্গের যুদ্ধে রুশরা পরাজিত হয়, কিন্তু অস্ট্রিয়ার বিরুদ্ধে গ্যালিসিয়ায় রুশরা সাফল্য পায়। এই যুদ্ধগুলো ইউরোপ জুড়ে ছড়িয়ে পড়ে এবং সত্যিকার অর্থে একটি বিশ্বযুদ্ধে রূপ নেয়। আশা করি তোমরা প্রথম বিশ্বযুদ্ধের কারণ ও শুরু পর্যন্ত ঘটনা বুঝতে পেরেছো। মনে রেখো, এই যুদ্ধের ফলেই বিশ্বের মানচিত্র বদলে যায়। কোনো প্রশ্ন থাকলে জিজ্ঞাসা করো।''',
